export function messageParameters(value:string):readonly string[] {
  return Object.freeze([...value.matchAll(/\{([a-z][a-zA-Z]*)\}/gu)].map(match=>match[1]??'').sort());
}
function buildMessages():Readonly<Record<Locale,Messages>> {
  const result={} as Record<Locale,Messages>,reference=[...rows.en.split('|'),...extraRows.en.split('|'),...appearanceRows.en,...READING_ROWS.en.split('|')];
  for(const {code} of LOCALES){
    const values=[...rows[code].split('|'),...extraRows[code].split('|'),...appearanceRows[code],...READING_ROWS[code].split('|')];
    if(values.length!==MESSAGE_KEYS.length||values.some(value=>!value.trim()))throw Error('I18N_MESSAGE_COUNT:'+code);
    for(const [index,value] of values.entries()){
      if(JSON.stringify(messageParameters(value))!==JSON.stringify(messageParameters(reference[index]??'')))throw Error('I18N_PLACEHOLDERS:'+code+':'+MESSAGE_KEYS[index]);
    }
    result[code]=Object.freeze(Object.fromEntries(MESSAGE_KEYS.map((key,index)=>[key,values[index]]))) as Messages;
  }
  return Object.freeze(result);
}
export const MESSAGES=buildMessages();
export const CATEGORY_LABELS:Readonly<Record<Locale,Readonly<Record<PublicEditorialCategory,string>>>>=Object.freeze(Object.fromEntries(LOCALES.map(({code})=>{
  const values=categoryRows[code].split('|');
  if(values.length!==PUBLIC_EDITORIAL_CATEGORIES.length||values.some(value=>!value.trim()))throw Error('I18N_CATEGORY_COUNT:'+code);
  return [code,Object.freeze(Object.fromEntries(PUBLIC_EDITORIAL_CATEGORIES.map((category,index)=>[category,values[index]])))];
}))) as Readonly<Record<Locale,Readonly<Record<PublicEditorialCategory,string>>>>;
